/* From Uiverse.io by Admin12121  - Tags: input, toggle, futuristic, input effect  */
.__UIV_SCOPE__ .div {
  --field-size: 50px;
  --field-border-color: #ccc;
  margin: 0 auto;
  font-size: 1rem;
  box-shadow:
    0 20px 25px -5px rgba(0, 0, 0, 0.1),
    0 10px 10px -5px rgba(0, 0, 0, 0.04);
  background: #ffffff;
  border-radius: 5px;
  position: relative;
  width: 300px;
  overflow: hidden;
  display: flex;
  background: white;
}

.__UIV_SCOPE__ .div input[type="checkbox"] {
  position: absolute;
  opacity: 0;
  width: var(--field-size);
  height: var(--field-size);
  cursor: pointer;
  padding: 0;
  margin: 0;
}

.__UIV_SCOPE__ .div input[type="checkbox"]:hover + span .svgi {
  display: none;
  /* Remove the background image */
}
.__UIV_SCOPE__ .div input[type="checkbox"]:hover + span .svgii {
  display: block;
}

.__UIV_SCOPE__ .div input[type="checkbox"]:checked + span .svgi {
  display: none; /* Remove the background image */
}

.__UIV_SCOPE__ .div input[type="checkbox"]:checked + span .svgii {
  display: block;
}

.__UIV_SCOPE__ .div input[type="checkbox"]:checked + span::before,
.__UIV_SCOPE__ .div input[type="checkbox"]:checked + span::after {
  pointer-events: none;
}

.__UIV_SCOPE__ .div input[type="checkbox"]:checked + span::after {
  transform: translateY(-100%);
}

.__UIV_SCOPE__ .div input[type="checkbox"]:checked + span::before {
  transform: translateY(100%);
}
.__UIV_SCOPE__ .div input[type="checkbox"] + span .svgii {
  display: none;
}
.__UIV_SCOPE__ .div input[type="checkbox"] + span,
.__UIV_SCOPE__ .svgi,
.__UIV_SCOPE__ .svgii {
  width: var(--field-size);
  height: var(--field-size);
  padding: 5px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  border-right: 1px solid var(--field-border-color);
  cursor: pointer;
}

.__UIV_SCOPE__ .div input[type="checkbox"] + span::after,
.__UIV_SCOPE__ .div input[type="checkbox"] + span::before {
  content: "";
  position: absolute;
  right: 0;
  height: 50%;
  left: var(--field-size);
  transition: all 0.3s cubic-bezier(0.23, 1, 0.32, 1);
  background: rgba(0, 0, 0, 0.075);
  z-index: 2;
  cursor: not-allowed;
}

.__UIV_SCOPE__ .div input[type="checkbox"] + span::after {
  top: 0;
}

.__UIV_SCOPE__ .div input[type="checkbox"] + span::before {
  bottom: 0;
}

.__UIV_SCOPE__ .div input[type="text"] {
  padding: 1em;
  border: 0;
  flex: 1;
  font-size: 1rem;
  --placeholder-color: #ababab;
  font-family: inherit;
}

.__UIV_SCOPE__ .div input[type="text"]::-webkit-input-placeholder {
  color: var(--placeholder-color);
}

.__UIV_SCOPE__ .div input[type="text"]:-ms-input-placeholder {
  color: var(--placeholder-color);
}

.__UIV_SCOPE__ .div input[type="text"]::-moz-placeholder {
  color: var(--placeholder-color);
}

.__UIV_SCOPE__ .div input[type="text"]:-moz-placeholder {
  color: var(--placeholder-color);
}
